package com.aoo.bcg.common.retry;import java.time.Duration;import java.util.Objects;import java.util.concurrent.Callable;import java.util.function.Predicate;
/** Explicit retry boundary requiring idempotency, transient classification, bounded exponential backoff and jitter. */
public final class ControlledRetry{public record Policy(int maxAttempts,Duration initialBackoff,Duration maximumBackoff,Duration maximumElapsed,double jitterRatio){public Policy{if(maxAttempts<1||initialBackoff==null||initialBackoff.isNegative()||maximumBackoff==null||maximumBackoff.compareTo(initialBackoff)<0||maximumElapsed==null||maximumElapsed.isNegative()||jitterRatio<0||jitterRatio>1)throw new IllegalArgumentException("invalid retry policy");}}private final Policy policy;private final Sleeper sleeper;private final Jitter jitter;public ControlledRetry(Policy policy,Sleeper sleeper,Jitter jitter){this.policy=Objects.requireNonNull(policy);this.sleeper=Objects.requireNonNull(sleeper);this.jitter=Objects.requireNonNull(jitter);}public<T>T execute(String idempotencyKey,Callable<T>operation,Predicate<Throwable>transientFailure)throws Exception{if(policy.maxAttempts()>1&&(idempotencyKey==null||idempotencyKey.isBlank()))throw new IllegalArgumentException("idempotency key required for retry");long started=System.nanoTime();for(int attempt=1;;attempt++)try{return operation.call();}catch(Exception failure){if(attempt>=policy.maxAttempts()||!transientFailure.test(failure))throw failure;long base=Math.min(policy.maximumBackoff().toNanos(),Math.multiplyExact(policy.initialBackoff().toNanos(),1L<<Math.min(30,attempt-1)));long delay=jitter.apply(base,policy.jitterRatio());if(System.nanoTime()-started+delay>policy.maximumElapsed().toNanos())throw failure;sleeper.sleep(Duration.ofNanos(delay));}}@FunctionalInterface public interface Sleeper{void sleep(Duration duration)throws InterruptedException;}@FunctionalInterface public interface Jitter{long apply(long baseNanos,double ratio);}}
